function cibToken(e){return getComputedStyle(document.body).getPropertyValue(e).trim()}function renderMonthlyChart(e,o,t,r){const n=document.getElementById(e);if(!n||"undefined"==typeof Chart)return;const d=()=>{const e=Chart.getChart(n);e&&e.destroy();const d=cibToken("--text-muted"),a=cibToken("--border");new Chart(n,{type:"bar",data:{labels:o,datasets:[{label:"Trabajado",data:t,backgroundColor:cibToken("--primary"),borderRadius:4},{label:"Objetivo",data:r,backgroundColor:cibToken("--zero-soft"),borderColor:cibToken("--border-strong"),borderWidth:1,borderRadius:4}]},options:{responsive:!0,plugins:{legend:{position:"top",labels:{color:d,boxWidth:12,boxHeight:12}}},scales:{x:{ticks:{color:d},grid:{display:!1}},y:{ticks:{color:d},grid:{color:a}}}}})};d(),document.addEventListener("themechange",d)}